// استخراج قطعی شماره موبایل و ایمیل از متن پیام کاربر
// (مدل زبانی در بازنویسی ارقام فارسی خطا می‌کند؛ اینجا با کد قطعی درمی‌آوریم)
const items = $input.all();
const it = items[0].json;
const msg = String((it.body && it.body.message) || '');
const fa2en = s => s.replace(/[۰-۹]/g, d => String('۰۱۲۳۴۵۶۷۸۹'.indexOf(d))).replace(/[٠-٩]/g, d => String('٠١٢٣٤٥٦٧٨٩'.indexOf(d)));
const norm = fa2en(msg);
const digits = norm.replace(/[\s\-().]/g, '');
let detected_phone = '';
const m = digits.match(/(?:\+98|0098|98|0)?9\d{9}/);
if (m) {
  let p = m[0];
  if (p.startsWith('+98')) p = '0' + p.slice(3);
  else if (p.startsWith('0098')) p = '0' + p.slice(4);
  else if (p.startsWith('98')) p = '0' + p.slice(2);
  else if (p.startsWith('9')) p = '0' + p;
  detected_phone = p;
}
const em = norm.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/);
it.body.detected_phone = detected_phone;
it.body.detected_email = em ? em[0] : '';
return items;
